77:   private convertirFechaHoraAEpoch(fecha: string, hora: string): number {
78:     if (!fecha || !hora) return 0;
79: 
80:     // Combinar fecha y hora en formato ISO (YYYY-MM-DDTHH:MM:SS)
81:     const fechaHoraString = `${fecha}T${hora}:00`;
82:     const fechaHora = new Date(fechaHoraString);
83: 
84:     // Obtener timestamp en segundos (Unix Epoch)
85:     return Math.floor(fechaHora.getTime() / 1000);
86:   }
