296:   timeValidator(control: any): { [key: string]: boolean } | null {
297:     const timeRegex = /^([01]?[0-9]|2[0-3]):([0-5][0-9])$/;
298:     if (control.value && !timeRegex.test(control.value)) {
299:       return { 'invalidTime': true };
