304:   onNombreApiChange(event: Event): void {
305:     const selectElement = event.target as HTMLSelectElement;
306:     const selectedIndex = parseInt(selectElement.value, 10);
307:     if (!isNaN(selectedIndex) && selectedIndex >= 0 && selectedIndex < this.apisInfo.length) {
308:       const selectedApi = this.apisInfo[selectedIndex];
309:       this.apiSeleccionada = { nombre: selectedApi.nombre, entorno: selectedApi.entorno };
310:     } else {
311:       this.apiSeleccionada = null;
312:     }
