315:   private fetchApiData(rootClienteId: string): void {
316:     const baseUrl = environment.ROLES_JBPM_SERVICE;
317:     const token = localStorage.getItem("access_token");
318:     const headers = {
319:       Authorization: `Bearer ${token}`,
320:       Accept: 'application/json',
321:     };
322:     const url = `${baseUrl}apis_cliente?cliente=${encodeURIComponent(rootClienteId)}`;
323:     from(fetch(url, { headers })).pipe(
324:       switchMap(response => {
325:         if (!response.ok) {
326:           return response.text().then(errorText => {
327:             throw new Error(`Error HTTP: ${response.status}, Detalles: ${errorText}`);
328:           });
329:         }
330:         return from(response.json());
331:       }),
332:       tap(data => { }),
333:       map(data => {
334:         if (data?.cliente?.api) {
335:           this.apisInfo = data.cliente.api.map((api: any) => {
336:             const nombre = api.nombre.startsWith('/') ? api.nombre.slice(1) : api.nombre;
337:             api.nombre = MAPEO_APIS[nombre] || nombre;
338:             return {
339:               nombre: api.nombre,
340:               entorno: api.entorno,
341:             };
342:           });
343:         }
344:         return data;
345:       }),
346:       tap(data => {
347:         window.dispatchEvent(new CustomEvent('apiDataFetched', { detail: data }));
348:       }),
349:       catchError(error => {
350:         console.error('Error al consultar la API:', error);
351:         return throwError(() => error);
352:       })
353:     ).subscribe();
354:   }
