356:   private funcionFormateoLog(jsonString: string): string {
357:     try {
358:       const jsonCompleto = JSON.parse(jsonString);
359:       let cadenaData = jsonCompleto.data;
360:       cadenaData = cadenaData.slice(0, -1);
361:       const subJson = JSON.parse(cadenaData);
362:       jsonCompleto.data = subJson;
363:       return JSON.stringify(jsonCompleto, null, 2);
364:     } catch (error) {
365:       return jsonString;
366:     }
367:   }
