369:   private transformarRespuesta(response: any): LogData[] {
370:     if (!response || !response.Data || !Array.isArray(response.Data)) {
371:       return [];
372:     }
373:     return response.Data.map((log: any) => ({
374:       MODIFICACION: log.tipo_log || 'Sin tipo',
375:       FECHA: log.fecha || 'Sin fecha',
376:       ROL: log.rol_responsable || 'Sin usuario',
377:       ACCIONES: 'Ver',
378:       ROLES: log.rol || 'Rol no encontrado',
379:       NOMBRERESPONSABLE: log.nombre_responsable || 'Sin nombre',
380:       DOCUMENTORESPONSABLE: log.documento_responsable || 'Sin documento',
381:       DIRECCIONACCION: log.direccion_accion || 'Sin direccion',
382:       APISCONSUMEN: log.apis_consumen || 'Sin apis',
383:       PETICIONREALIZADA: this.funcionFormateoLog(log.peticion_realizada || 'Sin peticion'),
384:       EVENTOBD: log.evento_bd || 'Sin evento de la BD',
385:       TIPOERROR: log.tipo_error || 'Sin tipo de error',
386:       MENSAJEERROR: log.mensaje_error || 'Sin mensaje de error'
387:     }));
388:   }
